import{_ as e,a0 as l,w as r,s as o,I as a,x as n,a1 as p,A as t,ao as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"ArchI0：Arch Linux 應用自動安裝腳本 | LCTT x X-CMD","titleTemplate":false,"description":"ArchI0：Arch Linux 應用自動安裝腳本 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ArchI0：Arch Linux 應用自動安裝腳本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ArchI0：Arch Linux 應用自動安裝腳本 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20170721 Arch Linux Applications Automatic Installation Script","title":"ArchI0：Arch Linux 應用自動安裝腳本","tag":"201808","desc":""},"relativePath":"201808/20170721 Arch Linux Applications Automatic Installation Script.md","filePath":"[post].md"}'),h={name:"201808/20170721 Arch Linux Applications Automatic Installation Script.md"};function d(u,s,g,k,A,b){const i=l("Link");return r(),o("div",null,[s[22]||(s[22]=a("h1",{id:"archi0-arch-linux-應用自動安裝腳本",tabindex:"-1"},[n("ArchI0：Arch Linux 應用自動安裝腳本 "),a("a",{class:"header-anchor",href:"#archi0-arch-linux-應用自動安裝腳本","aria-label":"Permalink to “ArchI0：Arch Linux 應用自動安裝腳本”"},"​")],-1)),s[23]||(s[23]=a("p",null,[a("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/07/ArchI0-Arch-Linux-Applications-Automatic-Installation-Script-720x340.png",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("Arch 用户你們好！今天，我偶然發現了一個叫做 “",-1)),s[2]||(s[2]=a("strong",null,"ArchI0",-1)),s[3]||(s[3]=n("” 的實用工具，它是基於命令列菜單的 Arch Linux 應用自動安裝腳本。使用此腳本是為基於 Arch 的發行版安裝所有必要的應用最簡易的方式。請注意",-1)),s[4]||(s[4]=a("strong",null,"此腳本僅適用於菜鳥級使用者",-1)),s[5]||(s[5]=n("。中高級使用者可以輕鬆掌握",-1)),p(i,{href:"http://www.ostechnix.com/getting-started-pacman/"},{default:t(()=>[...s[0]||(s[0]=[n("如何使用 pacman",-1)])]),_:1}),s[6]||(s[6]=n("來完成這件事。如果你想學習如何使用 Arch Linux，我建議你一個個手動安裝所有的軟件。對那些仍是菜鳥並且希望為自己基於 Arch 的系統快速安裝所有必要應用的用户，可以使用此腳本。",-1))]),s[24]||(s[24]=c(`<h3 id="archi0-–-arch-linux-應用自動安裝腳本" tabindex="-1">ArchI0 – Arch Linux 應用自動安裝腳本 <a class="header-anchor" href="#archi0-–-arch-linux-應用自動安裝腳本" aria-label="Permalink to “ArchI0 – Arch Linux 應用自動安裝腳本”">​</a></h3><p>此腳本的開發者已經制作了 <strong>ArchI0live</strong> 和 <strong>ArchI0</strong> 兩個腳本。你可以通過 ArchI0live 測試應用，無需安裝。這可能有助於在將腳本安裝到系統之前瞭解其實際內容。</p><h3 id="安裝-archi0" tabindex="-1">安裝 ArchI0 <a class="header-anchor" href="#安裝-archi0" aria-label="Permalink to “安裝 ArchI0”">​</a></h3><p>要安裝此腳本，使用如下命令通過 Git 克隆 ArchI0 腳本倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/SifoHamlaoui/ArchI0.git</span></span></code></pre></div><p>上面的命令會克隆 ArchI0 的 Github 倉庫內容，在你當前目錄的一個名為 ArchI0 的文件夾裏。使用如下命令進入此目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ArchI0/</span></span></code></pre></div><p>使用如下命令賦予腳本可執行權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x ArchI0live.sh</span></span></code></pre></div><p>使用如下命令執行腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ./ArchI0live.sh</span></span></code></pre></div><p>此腳本需要以 root 或 sudo 用户身份執行，因為安裝應用需要 root 權限。</p><blockquote><p><strong>注意：</strong> 有些人想知道此腳本中開頭的那些命令是做什麼的，第一個命令是下載 <strong>figlet</strong>，因為此腳本的 logo 是使用 figlet 顯示的。第二個命令是安裝用來打開並查看許可協議文件的 <strong>Leafpad</strong>。第三個命令是安裝用於從 sourceforge 下載文件的 <strong>wget</strong>。第四和第五個命令是下載許可協議文件並用 leafpad 打開。此外，最後的第 6 條命令是在閲讀許可協議文件之後關閉它。</p></blockquote><p>輸入你的 Arch Linux 系統架構然後按回車鍵。當其請求安裝此腳本時，鍵入 <code>y</code> 然後按回車鍵。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/07/sk@sk-ArchI0_003.png" alt=""></p><p>一旦開始安裝，將會重定向至主菜單。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/07/sk@sk-ArchI0_004-1.png" alt=""></p><p>正如前面的截圖， ArchI0 包含有 13 類、90 個容易安裝的程序。這 90 個程序剛好足夠配置一個完整的 Arch Linux 桌面，可執行日常活動。鍵入 <code>a</code> 可查看關於此腳本的信息，鍵入 <code>q</code> 可退出此腳本。</p><p>安裝後無需執行 ArchI0live 腳本。可以直接使用如下命令啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ArchI0</span></span></code></pre></div><p>它會每次詢問你選擇 Arch Linux 發行版的架構。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>This script Is under GPLv3 License</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Preparing To Run Script</span></span>
<span class="line"><span> Checking For ROOT: PASSED</span></span>
<span class="line"><span> What Is Your OS Architecture? {32/64} 64</span></span></code></pre></div><p>從現在開始，你可以從主菜單列出的類別選擇要安裝的程序。要查看特定類別下的可用程序列表，輸入類別號即可。舉個例子，要查看<strong>文本編輯器</strong>分類下的可用程序列表，輸入 <strong>1</strong> 然後按回車鍵。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>This script Is under GPLv3 License</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ R00T MENU ]</span></span>
<span class="line"><span>Make A Choice</span></span>
<span class="line"><span> 1) Text Editors</span></span>
<span class="line"><span> 2) FTP/Torrent Applications</span></span>
<span class="line"><span> 3) Download Managers</span></span>
<span class="line"><span> 4) Network managers</span></span>
<span class="line"><span> 5) VPN clients</span></span>
<span class="line"><span> 6) Chat Applications</span></span>
<span class="line"><span> 7) Image Editors</span></span>
<span class="line"><span> 8) Video editors/Record</span></span>
<span class="line"><span> 9) Archive Handlers</span></span>
<span class="line"><span> 10) Audio Applications</span></span>
<span class="line"><span> 11) Other Applications</span></span>
<span class="line"><span> 12) Development Environments</span></span>
<span class="line"><span> 13) Browser/Web Plugins</span></span>
<span class="line"><span> 14) Dotfiles</span></span>
<span class="line"><span> 15) Usefull Links</span></span>
<span class="line"><span> ------------------------</span></span>
<span class="line"><span> a) About ArchI0 Script</span></span>
<span class="line"><span> q) Leave ArchI0 Script</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Choose An Option: 1</span></span></code></pre></div><p>接下來，選擇你想安裝的程序。要返回至主菜單，輸入 <code>q</code> 然後按回車鍵。</p><p>我想安裝 Emacs，所以我輸入 <code>3</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>This script Is under GPLv3 License</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ TEXT EDITORS ]</span></span>
<span class="line"><span> [ Option ] [ Description ]</span></span>
<span class="line"><span> 1) GEdit</span></span>
<span class="line"><span> 2) Geany</span></span>
<span class="line"><span> 3) Emacs</span></span>
<span class="line"><span> 4) VIM</span></span>
<span class="line"><span> 5) Kate</span></span>
<span class="line"><span> ---------------------------</span></span>
<span class="line"><span> q) Return To Main Menu</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Choose An Option: 3</span></span></code></pre></div><p>現在，Emacs 將會安裝至你的 Arch Linux 系統。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/07/pacman-as-superuser_005.png" alt=""></p><p>所選擇的應用安裝完成後，你可以按回車鍵返回主菜單。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>毫無疑問，此腳本讓 Arch Linux 用户使用起來更加容易，特別是剛開始使用的人。如果你正尋找快速簡單無需使用 pacman 安裝應用的方法，此腳本是一個不錯的選擇。試用一下並在下面的評論區讓我們知道你對此腳本的看法。</p><p>就這些。希望這個工具能幫到你。我們每天都會推送實用的指南。如果你覺得我們的指南挺實用，請分享至你的社交網絡，專業圈子並支持我們。</p><p>乾杯！</p><hr>`,35)),a("p",null,[s[8]||(s[8]=n("via: ",-1)),p(i,{href:"https://www.ostechnix.com/archi0-arch-linux-applications-automatic-installation-script/"},{default:t(()=>[...s[7]||(s[7]=[n("https://www.ostechnix.com/archi0-arch-linux-applications-automatic-installation-script/",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=n("作者：",-1)),p(i,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[9]||(s[9]=[n("SK",-1)])]),_:1}),s[14]||(s[14]=n(" 選題：",-1)),p(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[10]||(s[10]=[n("lujun9972",-1)])]),_:1}),s[15]||(s[15]=n(" 譯者：",-1)),p(i,{href:"https://github.com/fuowang"},{default:t(()=>[...s[11]||(s[11]=[n("fuowang",-1)])]),_:1}),s[16]||(s[16]=n(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[12]||(s[12]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=n("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[17]||(s[17]=[n("LCTT",-1)])]),_:1}),s[20]||(s[20]=n(" 原創編譯，",-1)),p(i,{href:"https://linux.cn/"},{default:t(()=>[...s[18]||(s[18]=[n("Linux中國",-1)])]),_:1}),s[21]||(s[21]=n(" 榮譽推出",-1))])])}const I=e(h,[["render",d]]);export{x as __pageData,I as default};
